// This is efficient! For each X, we can do a BFS/DFS on the subgraph of nodes with a[i] >= X and check if any component has size >= k.

// Binary search on X from 1 to max(a).

function canAchieve($n, $k, $a, $adj, $X) {
    $visited = array_fill(0, $n, false);
    for ($i = 0; $i < $n; $i++) {
        if ($a[$i] >= $X && !$visited[$i]) {
            // BFS/DFS to find component size
            $queue = array($i);
            $visited[$i] = true;
            $size = 0;
            while (!empty($queue)) {
                $v = array_pop($queue);
                $size++;
                foreach ($adj[$v] as $u) {
                    if ($a[$u] >= $X && !$visited[$u]) {
                        $visited[$u] = true;
                        $queue[] = $u;
                    }
                }
            }
            if ($size >= $k) {
                return true;
            }
        }
    }
    return false;
}

$lo = 1;
$hi = 0;
for ($i = 0; $i < $n; $i++) {
    if ($a[$i] > $hi) $hi = $a[$i];
}

$ans = 1;
while ($lo <= $hi) {
    $mid = intdiv($lo + $hi, 2);
    if (canAchieve($n, $k, $a, $adj, $mid)) {
        $ans = $mid;
        $lo = $mid + 1;
    } else {
        $hi = $mid - 1;
    }
}

echo $ans . "\n";
